    if (pos < 1 || pos > s[0] || len < 0 || pos + len - 1 > s[0])
        return 0;
    for (i = 1; i <= len; i++)
        sub[i] = s[pos + i - 1];;
    sub[0] = (char)len;;
    return 1;
}

