/* 返回 T 在 S 中首次出现的位置（从 1 开始），不存在返回 0 */
int Index(const char S[], const char T[])
{
    int n = (int)strlen(S), m = (int)strlen(T), i, j;

    if (m == 0 || m > n)
        return 0;
    for (i = 0; i <= n - m; i++)
    {
        for (j = 0; j < m; j++)
            if (S[i + j] != T[j])
                break;
        if (j == m)
            return i + 1;
    }
    return 0;
}

int main(void)
{
    char S[100], T[100];

    scanf("%99s %99s", S, T);
    printf("%d\n", Index(S, T));
    return 0;
}
