} Triple;

typedef struct
{
    Triple data[MAXSIZE + 1];
    int mu, nu, tu;     /* 行数、列数、非零元素个数 */
} TSMatrix;

/* 按行序为主序读入矩阵，建立三元组顺序表 */
void CreateSMatrix(TSMatrix *M)
{
    int r, c, x;

    if (scanf("%d %d", &M->mu, &M->nu) != 2)
    {
        M->mu = 0;
        M->nu = 0;
        M->tu = 0;
        return;
    }
    M->tu = 0;
    for (r = 1; r <= M->mu; r++)
        for (c = 1; c <= M->nu; c++)
        {
            if (scanf("%d", &x) != 1)
                x = 0;
            if (x != 0 && M->tu < MAXSIZE)
            {
                M->tu++;
                M->data[M->tu].i = r;
                M->data[M->tu].j = c;
                M->data[M->tu].e = x;
            }
        }
}

/* 快速转置：num[col] 为原矩阵每列非零元个数，
   cpot[col] 为该列第一个非零元在 T->data 中的适当位置 */
void FastTransposeSMatrix(const TSMatrix *M, TSMatrix *T)
{
    int col, t, p, q;
    int num[MAXSIZE + 1], cpot[MAXSIZE + 1];

    T->mu = M->nu;
    T->nu = M->mu;
    T->tu = M->tu;
    if (T->tu == 0)
        return;
    for (col = 1; col <= M->nu; col++)
        num[col] = 0;
    for (t = 1; t <= M->tu; t++)
    {
        col = M->data[t].j;
        num[col]++;
    }
    cpot[1] = 1;
    for (col = 2; col <= M->nu; col++)
        cpot[col] = cpot[col - 1] + num[col - 1];
    for (p = 1; p <= M->tu; p++)
    {
        col = M->data[p].j;
        q = cpot[col];
        T->data[q].i = M->data[p].j;
        T->data[q].j = M->data[p].i;
        T->data[q].e = M->data[p].e;
        cpot[col]++;
    }
}

int main(void)
{
    TSMatrix M, T;
    int k;

    CreateSMatrix(&M);
    FastTransposeSMatrix(&M, &T);
    printf("%d %d %d\n", T.mu, T.nu, T.tu);
    for (k = 1; k <= T.tu; k++)
        printf("%d %d %d\n", T.data[k].i, T.data[k].j, T.data[k].e);
    return 0;
}

