下列程序递归求广义表的深度（每行输入一个广义表，输出其深度）。写出程序的运行结果。
```
#include <stdio.h>

#define MAXLEN 100

/* s 是广义表的字符串形式，如 "(a,(b,c))"；pos 为当前扫描位置 */
int Depth(const char *s, int *pos)
{
    int max = 0, d;

    (*pos)++;                       /* 跳过左括号 */
    while (s[*pos] != '\0' && s[*pos] != ')')
    {
        if (s[*pos] == '(')
        {
            d = Depth(s, pos);      /* 递归求子表深度 */
            if (d > max)
                max = d;
        }
        else
            (*pos)++;               /* 原子结点，深度记 0 */
        if (s[*pos] == ',')
            (*pos)++;
    }
    (*pos)++;                       /* 跳过右括号 */
    return max + 1;
}

int main(void)
{
    char s[MAXLEN];
    int pos;

    while (scanf("%99s", s) == 1)
    {
        pos = 0;
        printf("%d\n", Depth(s, &pos));
    }
    return 0;
}
